@PostMapping("/shareCheck.do")
    @ApiOperation("检查分享是否满足条件")
    public GenericRpcResponse shareCheck(@RequestHeader("userId") String userId, @RequestHeader("appCode") String appCode, @RequestBody SubmitUnderwriteRequestDTO submitUnderwriteRequestDTO) {
        try {
            log.info("检查分享是否满足条件 - ->userId：{},appCode：{},RequestBody:{}", userId, appCode, JSON.toJSONString(submitUnderwriteRequestDTO));
            //获取用户明细
            UserInfoVO userInfoVO = userInfrastructure.queryOneselfInfo(userId, appCode);
            if (userInfoVO == null) {
                return GenericRpcResponse.fail(null, ErrorEnum.ECLIPSE_FRONT_ERROR_CERT_NO.getErrorCode());
            }

            Response<PreUnderwriteResDTO> reposeDTOResponse = vehicleOnlineInfrastructure.shareCheck(submitUnderwriteRequestDTO);

            log.info("检查分享是否满足条件 - ->{}", JSON.toJSONString(reposeDTOResponse));

            if (reposeDTOResponse.isSuccess()) {
                return GenericRpcResponse.success(reposeDTOResponse.getContent());
            } else {
                return GenericRpcResponse.fail(reposeDTOResponse.getRespCode(), reposeDTOResponse.getFailCause(), null);
            }
        } catch (Exception e) {
            log.error(e.getMessage(), e);
            return GenericRpcResponse.fail(null, e.getMessage());
        }
    }

public static void info(String format, Object... args) {
        if (Level.INFO_INT >= logLevel) {
            log.info(format, args);
        }
    }

public AdvertiseResource info(String type, String layout,String title) {
        notBlank(type, "type is required!");

        this.type = type;
        this.layout = layout;
        this.advertiseResourceTitle = title;

        return this;
    }

public AdvertiseResourceItem info(String title, String imageUrl, String link, String linkType) {
        this.title = title;
        this.imageUrl = imageUrl;
        this.link = link;
        this.linkType = linkType;

        return this;
    }

@PostMapping("/submitForUnderwriting.do")
    @ApiOperation("提交核保")
    public GenericRpcResponse submitForUnderwriting(@RequestHeader("userId") String userId, @RequestHeader("appCode") String appCode, @RequestBody SubmitUnderwriteRequestDTO submitUnderwriteRequestDTO) {
        try {
            log.info("提核入参  - ->userId：{},appCode：{},RequestBody:{}", userId, appCode, JSON.toJSONString(submitUnderwriteRequestDTO));
            //获取用户明细
            UserInfoVO userInfoVO = userInfrastructure.queryOneselfInfo(userId, appCode);
            if (userInfoVO == null) {
                return GenericRpcResponse.fail(null, ErrorEnum.ECLIPSE_FRONT_ERROR_CERT_NO.getErrorCode());
            }

            //设置投保人信息
            submitUnderwriteRequestDTO.setCustomerCode(userId);

            //执行提核
            Response<SubmitUnderwriteResponseDTO> reposeDTOResponse = vehicleOnlineInfrastructure.submitForUnderwriting(submitUnderwriteRequestDTO);

            log.info("提核出参 - ->{}", JSON.toJSONString(reposeDTOResponse));

            if (reposeDTOResponse.isSuccess()) {
                return GenericRpcResponse.success(reposeDTOResponse.getContent());
            } else {
                return GenericRpcResponse.fail(reposeDTOResponse.getRespCode(), reposeDTOResponse.getFailCause(), null);
            }
        } catch (Exception e) {
            log.error(e.getMessage(), e);
            return GenericRpcResponse.fail(null, e.getMessage());
        }
    }
